DROP TABLE IF EXISTS `health_assessments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `health_assessments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT '用户ID',
  `record_id` bigint unsigned DEFAULT NULL COMMENT '关联档案ID（多档案）',
  `form_id` bigint unsigned NOT NULL COMMENT '量表ID',
  `form_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '量表名称快照',
  `assessor_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1自助2服务人员',
  `staff_id` bigint unsigned DEFAULT NULL COMMENT '评估服务人员ID',
  `answers` json DEFAULT NULL COMMENT '答案{key:选中label}',
  `total_score` decimal(6,1) DEFAULT NULL COMMENT '总分',
  `level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评估等级',
  `conclusion` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评估结论',
  `suggestions` json DEFAULT NULL COMMENT '建议数组',
  `symptom_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '症状描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_health_assessments_user_id` (`user_id`),
  KEY `idx_health_assessments_form_id` (`form_id`),
  KEY `idx_health_assessments_record_id` (`record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='健康评估记录表';
