--
-- Table structure for table `printers`
--

DROP TABLE IF EXISTS `printers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `printers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '打印机ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印机名称',
  `type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '类型: 1=飞鹅 2=通用云打印',
  `feie_user` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '飞鹅云账号',
  `feie_ukey` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '飞鹅云UKey(API密钥)',
  `feie_sn` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '飞鹅云打印机编号',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态: 1=启用 0=禁用',
  `auto_print` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否自动打印小票: 0=否 1=是',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否为默认打印机: 0=否 1=是',
  `print_count` int unsigned NOT NULL DEFAULT '0' COMMENT '累计打印次数',
  `last_print_at` datetime DEFAULT NULL COMMENT '最后打印时间',
  `remark` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_printers_default` (`is_default`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='打印机表';
/*!40101 SET character_set_client = @saved_cs_client */;

