INSERT INTO `products` VALUES (20020,744,'一字扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\n盖外尺寸：600MM\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032502633.png?e=1786170532&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3Ax6rA5qY_669iHpxi9-LboXWQrzs%3D\"]',22.00,40.00,100,'份',1,NULL,1,0,0.00,0.00,0,937,0,1,NULL,'2026-05-29 13:29:26','2026-08-08 13:29:04'),(20021,744,'L型扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\n盖外尺寸：600*400MM\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032627448.png?e=1786170518&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AOExKt02i6khOC2NcEpL4dJj2Kkk%3D\"]',74.00,99.00,10,'份',1,NULL,1,0,0.00,0.00,0,872,0,1,NULL,'2026-05-29 13:30:44','2026-08-08 13:28:50'),(20022,744,'马桶扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780034010146.png?e=1786170508&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AO7i1x8XL0vNWNHkcmI960K19UhE%3D\"]',80.00,110.00,10,'份',1,NULL,1,0,0.00,0.00,0,879,0,1,NULL,'2026-05-29 13:32:20','2026-08-08 13:28:37'),(20023,746,'淋浴凳','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢/镀锌内管，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032792752.png?e=1786170494&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3APPxsSV7b-ZHexTsHperSW4seiWg%3D\"]',290.00,350.00,10,'份',1,NULL,1,0,0.00,0.00,0,1173,0,2,NULL,'2026-05-29 13:33:23','2026-08-08 13:28:27'),(20024,747,'助行器-双弯铝合金/带白板不带轮','品名；铝合金助行器 带轮子可两用                             壁厚；1.2                                        尺寸；49*49*74CM(长宽高)                         材质；铝合金环保负离子喷粉                          称重；200斤以上                                   适用场合；家用 老年公寓 疗养院 医院','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032902030.png