9.00,20,'份',1,NULL,1,0,0.00,0.00,0,71,0,1,NULL,'2026-08-19 15:29:04','2026-08-26 18:12:52'),(20312,771,'适老沙发','\"三人位\n实木框架：采用进口橡胶木\n海绵：靠背+坐垫为高密高弹棉\n布料：优质国产面料\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124589951.png?e=1787742739&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AJVLX8nyV1r2qedc-WNoDxgZDH-A%3D\"]',2500.00,2599.00,10,'份',1,NULL,1,0,0.00,0.00,0,64,0,1,NULL,'2026-08-19 15:29:58','2026-08-26 18:12:36'),(20313,772,'\"防褥疮气床垫  （波动喷气型）\"','\"1.波动睡眠功能\n2.PVC加厚面料且不滑动，波动睡眠功能舒适静音，透气\n3.加厚面料，抑制细菌，承载力大，单条气囊可更换、不移位和滑动\n4.平铺尺寸为：93*200CM,充气后85*185cm\n5.≥22条独立气囊\n6.充气流量≥6L/min\n7.波动循环周期为12分钟\n8. 输入功率≤20伏安 承重≥135KG\n9.床垫由：床垫，气泵。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124694424.png?e=1787742710&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AEl0elOlxK6PXkbkQJNP_mRYPRn0%3D\"]',360.00,410.00,100,'份',1,NULL,1,0,0.00,0.00,0,1324,0,1,NULL,'2026-08-19 15:31:36','2026-08-26 18:12:02'),(20314,772,'中曲防褥疮充气床垫','\"防褥疮床垫由充气泵和床垫组成：\n1.床垫由两组共34根气囊组成，分别与气泵的两组气路相通，有规律的交替供气造成气垫的循环波动，使患者肌肉组织经常变换受压部位，免于固定积压于同一点，并能促进血液循环，从而有效的阻止褥疮的产生。\n2.充气泵为安全型圆棱角设计，调节旋钮简单易用。\n3.气泵额定电压220V，频率50Hz；\n4.气泵压力范围：50~110mmHg，流量范围：5~8升/分钟，交替波动周期：10分钟；\n5.充气泵和床垫的连接均使用优质软管；\n6.床垫材质为PVC复合布；布料具有防水功能，易清洁。\n7、规格：床垫平铺尺寸：2000*900*75mm；\n8、承压重量不大于135kg；\n9、气床垫充气后柔软、舒适，拥有良好的吸湿透气性能，保持卧床                                          使用者皮肤的干爽舒适，有经久耐用、不易老化、容易清洁、保养得特点，床垫表面采用两管波动起伏，具有转移身体受力点的优点；可以配合中区护理床左右翻身.\n10、适用于移动不便者，老年人，长期卧床人士使用。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124743657.png?e=1787742698&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AorooZ3Y-PuSpYEyzE5no806-7Zk%3D\"]',420.00,499.00,100,'份',1,NULL,1,0,0.00,0.00,0,328,0,1,NULL,'2026-08-19 15:32:27','2026-08-26 18:11:47'),(20315,772,'\"褥疮气床垫 (球形波动)\"','\"1.循环波动喷气\n2.PVC加厚膜，不滑动，波动功能，舒适静音。\n3.加厚材质，抑制细菌，承载力大，不移位和滑动\n4.平铺尺寸为：90*200CM,充气后80*180cm\n5.充气流量≥6L/min\n6.波动循环周期为12分钟\n7. 输入功率≤20伏安 承重≥135KG\n8.床垫由：床垫，气泵\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124792623.png?e=1787742676&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3Aazi4wo02u7btbeON6cURY6Mrap4%3D\"]',220.00,290.00,60,'份',1,NULL,1,0,0.00,0.00,0,932,0,1,NULL,'2026-08-19 15:33:17','2026-08-26 18:11:25'),(20316,772,'床头柜','\"常规颜色： 浅蓝、蓝色、绿色、白色、粉色、橘红\n1、规格尺寸：450*420*740mm，因塑料制品收缩率的变化产品误差（±10mm）；\n2、床头柜整体采用优级改性塑料注塑成型，板材料强度高，外形美观大方；\n3、床头柜由柜体、面盖、柜门、抽屉、拉板、毛巾架等组成；\n4 、柜体形状为圆弧形，左右两侧面配有折叠隐藏式毛巾架，需用时将伸出，不用时收拢，\n放置在柜体侧面型体内，角度范围 90 度；柜体底部可安装万向轮便于移动；\n抽屉面板外形为圆弧状，面板下方有抽屉拉手孔，便于拉、关抽屉；\n5、柜门内侧设有内置储物盒，存取小型物品更为便捷；\n6、柜体内设有隔板，可根据物品的高度调节隔板的位置，具有两层调节功能；\n7、柜体侧板有圆弧形加强筋，柜体支撑强度和牢固性更佳；加强筋内凸位置与隔板凹槽配\n合，增加隔板位置稳定性；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124988978.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3ADHV2pbjbbE_xzbj-W0jAqsASXcY%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787124989325.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3ApOtDdpcErbdNloT7gBPJrtm1vhw%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125021555.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AemoODlVQ4jk7NSPbVKfhnqHwVbs%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125029763.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AKJRPotH2NxXiLLRTkK0J6vqcMDQ%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125038070.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3ArKlIfrXYQHfIQuWwTbgkQWLuwes%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125044105.png?e=1787742658&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3Aqr-cK-XfV2dPNiqwqtK082QxHkA%3D\"]',40.00,60.00,100,'份',1,NULL,1,0,0.00,0.00,0,273,0,1,NULL,'2026-08-19 15:40:09','2026-08-26 18:11:14'),(20317,772,'\"木制床头柜 定制款\"','\"一抽屉一柜，加把手\n1.床头柜尺寸：420*400*685mm(人工测量稍有误差）\n2.整体柜采用颗粒板打造，优质板材加工制作木纹清晰纹理细腻。\n3.容量大，使用方便。（颜色仅供参考）\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125328308.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AwlvaWJnK5vC1GH4tYB1jvIc0Xsg%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125342107.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3At4bs1dHsNrzUg9MehqssHRTH2jk%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125358554.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AGlwJxj3B0_oEdpQQhaxRfLcvTQo%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125358774.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AuhJiPNvzXq_wd0OnK3rSogxYNZ8%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125358988.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3A7wgjmTWO9VgD2jrUUx2D3jkOjGQ%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125359188.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AIFBfIf2Slrhg4C8FOeQYeFTjapQ%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125359526.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AhQOUlgRDikvZu8iWQrjmFXH3fuM%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125359735.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AcUQH-TbQr3sBrWXHKf1Db4amQ1Q%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125359968.png?e=1787742641&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AHwzHjX4SdW2N2Cnq6EhYdrCLd7M%3D\"]',360.00,400.00,50,'份',1,NULL,1,0,0.00,0.00,0,1448,0,1,NULL,'2026-08-19 15:45:01','2026-08-26 18:10:54'),(20318,772,'移动餐桌','\"豪华ABS床边桌\n一：桌面采用ABS材料制作；\n二：气控升降装置可以根据个人需要和喜好随意调节高度；\n三：4个2.5寸带刹车脚轮，既能随意移动位置又能使停靠更稳；\n四：立柱和底座采用高精密无缝钢管材质，表面除锈，静电喷涂，高档环保喷塑，持久耐用，美观大方；每台重约18公斤；沉稳！\n外形尺寸：可升降桌面长82厘米 宽45厘米 厚度3.3厘米 ； 底脚尺寸：81.8x48.5x11厘米， 整体升降高度可以在70--94厘米之间调节；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125568055.png?e=1787742612&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AukDsyWagc4nQQVdg_-sNDlEUpPM%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125568577.png?e=1787742612&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AROuTJZNefFEyx2awcATtN9RuceE%3D\"]',480.00,560.00,30,'份',1,NULL,1,0,0.00,0.00,0,376,0,1,NULL,'2026-08-19 15:46:52','2026-08-26 18:10:26'),(20319,772,'输液椅 双人位','\"双人位 输液椅\n冷轧钢静电喷漆\n1.5米宽度0.66米高度0.92米\n横梁1.0 腿1.2壁厚，配输液杆\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125703752.png?e=1787742591&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3A49bj4kSTRgaWGF6brq7aKv1jNGc%3D\"]',760.00,815.00,50,'份',1,NULL,1,0,0.00,0.00,0,1865,0,1,NULL,'2026-08-19 15:48:32','2026-08-26 18:10:00'),(20320,772,'护栏','\"上杆92.5cm ，下杆85cm   总高35cm   （手工测量稍有误差）。\n每个护栏配置2个安装铁件。\n上杆铝合金，立柱不锈钢，下杆及安装固定片为碳钢喷涂材质。\n护栏可折叠，可使用于家庭卧室床，钢板床，经济适用，安装方便，结实耐用。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125811222.png?e=1787742574&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AMGTOvsgZ8p4KktT2Ik0-BVeXa4I%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125811469.png?e=1787742574&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3ACD0G43rmk7ePwNS7nMDfnEq7rZI%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125811757.png?e=1787742574&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3ASW4FN1Cp33tg9A3FPWhmpWT9VKA%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125811935.png?e=1787742574&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AyvGrqO0uVKqIyQ2wNej8Pwwtcik%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787125836247.png?e=1787742574&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AJugCIsN_QHrWUoCnabGAptx_SQU%3D\"]',90.00,130.00,100,'份',1,NULL,1,0,0.00,0.00,0,1320,0,1,NULL,'2026-08-19 15:52:10','2026-08-26 18:09:48'),(20321,773,'冰壶桌游','作用：锻炼老年人对手臂力量的控制，团队协作能力，提升老年人的参与感、荣誉感、价值感，在竞技中，丰富老年人的生活乐趣。\n\"尺寸:2400*600*780；\n材质：实木橡胶木；\n冰壶直径：11cm；\n包含：红色冰壶*4\n         蓝色冰壶*4；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126083148.png?e=1787742562&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AOcZj3fCjoSKrU9XEwtztwzFCK_M%3D\"]',6400.00,6499.00,10,'份',1,NULL,1,0,0.00,0.00,0,10,0,1,NULL,'2026-08-19 15:54:53','2026-08-26 18:09:31'),(20322,773,'台球桌游','作用：锻炼老年人对手臂力量的控制，团队协作能力，同时，对于长期坐轮椅的老人，同样也可以参与其中，提升老年人的参与感、荣誉感、价值感，在竞技中，丰富老年人的生活乐趣。\n\"尺寸:1200*1200*850\n材质：实木橡胶木\n包含：球杆2根；台球1套；集球三脚架1个；伸缩球杆2个；收球器1个；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126148208.png?e=1787742545&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AlWZEqM_xfrgf-v7NRKaRMeIaCLU%3D\"]',4600.00,4699.00,10,'份',1,NULL,1,0,0.00,0.00,0,15,0,1,NULL,'2026-08-19 15:55:51','2026-08-26 18:09:13'),(20323,773,'弹球桌游','溜溜球桌为一款手指弹球桌、老年人通过手指在发球区向目标球洞内弹射，球面分为4层，由外向内分别为1分、2分、5分、10分，球桌可1-4人同时操作，每人10颗球，通过手指发力将球弹射至不同分数的球洞中，最终得分最高的为获胜一方。\n\"尺寸:1100*1100*780;\n材质：实木橡胶木；\n包含：四色球各10颗，一共40颗；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126200658.png?e=1787742517&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AOOpYr-T-9pVpeGR1HnMG3eLAKPM%3D\"]',3400.00,3489.00,10,'份',1,NULL,1,0,0.00,0.00,0,52,0,1,NULL,'2026-08-19 15:56:44','2026-08-26 18:08:49'),(20324,773,'弹射棋桌游','\"弹射棋是一种策略性强的棋类游戏，其玩法通常包括以下几个方面：\n1. 棋盘设置：弹射棋的棋盘由多个格子组成，一般呈长方形。棋盘上会有一些特殊的格子，如起始格、终点格、障碍格等。\n2. 棋子布置：每个玩家在游戏开始时拥有一定数量的棋子，这些棋子通常放在棋盘的起始格上。\n3. 轮流行动：玩家轮流进行游戏，每次行动可以选择一个棋子进行弹射。\n4. 弹射规则：玩家选择一个棋子后，可以沿着棋盘上的线路进行弹射。弹射的距离和方向由玩家自行决定，但通常受到一些规则的限制，如只能弹射到相邻的空格或只能沿着特定的线路移动。\n5. 目标达成：玩家的目标通常是让自己的棋子尽快到达终点格。\"\n\"尺寸:1100*500*780;\n包含：实木橡胶木；\n配件：四色球各四色原木块各5颗，共计20颗；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126246305.png?e=1787742497&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3AecayyS0-CncGMDzcJx_Jsu-xQPo%3D\"]',3200.00,3299.00,10,'份',1,NULL,1,0,0.00,0.00,0,120,0,1,NULL,'2026-08-19 15:57:30','2026-08-26 18:08:33'),(20325,773,'一桌四椅','作用：配合策略类游戏，提高老年人的动手能力和动脑能力，增加闲暇时间的乐趣。\n\"尺寸:900*900*750;\n材质：实木橡胶木；\n桌边设计适老化扶手\n和拐杖凹槽；\n桌板下设计田字格储物盒；\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126337400.png?e=1787742086&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3Agd3qjU95EqLlPW-G-ne2Th9vIoE%3D\"]',2500.00,2589.00,10,'份',1,NULL,1,0,0.00,0.00,0,23,0,1,NULL,'2026-08-19 15:59:03','2026-08-26 18:01:35'),(20326,773,'十二游戏盘','\"作用：各种颜色，锻炼老年人的色彩辨别能力和视力；\n      各种颜色对应的数量，锻炼老年人的动脑计算能力；\n      各种颜色的路径，锻炼老年人的手部稳定能力；\n      此类游戏有助于提高老年人的手脑协调、手眼协调的能力。\"\n\"游戏盘数量：12个\n游戏盘尺寸：50*50\n材质：实木橡胶木；\n收纳柜尺寸：1100*600*800\n材质：环保E0级颗粒板，用来收纳12个游戏盘\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126412143.png?e=1787742028&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3Ak8KDTBCVrDqYw5aSVRaLXgC4HXM%3D\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1787126415715.png?e=1787742028&token=1FctZeFOq4pUyZ55WhkfyzU9rI31anReup9lHbkF%3APe9QhF8AphNRotcFdKtolV_AldA%3D\"]',5200.00,5299.00,10,'份',1,NULL,1,0,0.00,0.00,0,85,0,1,NULL,'2026-08-19 16:00:24','2026-08-26 18:01:22');
